# The pattern behind next-greater, largest-rectangle, stock-span and
# daily-temperatures. Each index is pushed and popped once, so O(n).
def next_greater(a: list[int]) -> list[int]:
    res = [-1] * len(a)
    stack: list[int] = []              # indices, values decreasing
    for i, x in enumerate(a):
        while stack and a[stack[-1]] < x:
            res[stack.pop()] = x
        stack.append(i)
    return res

# Sliding window maximum with a deque. Use deque, not list — list.pop(0) is O(n).
from collections import deque

def window_max(a: list[int], k: int) -> list[int]:
    dq: deque[int] = deque()           # indices
    out: list[int] = []
    for i, x in enumerate(a):
        while dq and dq[0] <= i - k:
            dq.popleft()               # fell out of the window
        while dq and a[dq[-1]] <= x:
            dq.pop()                   # dominated by x, can never be the max
        dq.append(i)
        if i >= k - 1:
            out.append(a[dq[0]])
    return out

/* A stack is an array plus a top index. */
typedef struct { int *data; int top, cap; } Stack;

void st_push(Stack *s, int x) { s->data[++s->top] = x; }
int  st_pop(Stack *s)         { return s->data[s->top--]; }
int  st_peek(const Stack *s)  { return s->data[s->top]; }
int  st_empty(const Stack *s) { return s->top < 0; }   /* init top = -1 */

/* A queue needs head and tail. Wrap them modulo cap (a circular buffer),
   otherwise the array is exhausted after cap total pushes even if empty. */
typedef struct { int *data; int head, tail, count, cap; } Queue;

void q_push(Queue *q, int x) {
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % q->cap;
    q->count++;
}

int q_pop(Queue *q) {
    int x = q->data[q->head];
    q->head = (q->head + 1) % q->cap;
    q->count--;
    return x;
}

/* Monotonic stack — next greater element. Each index is pushed and popped
   at most once, so O(n). */
void nextGreater(const int *a, int n, int *res) {
    int *st = malloc((size_t) n * sizeof *st);
    int top = -1;
    for (int i = 0; i < n; i++) res[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && a[st[top]] < a[i]) res[st[top--]] = a[i];
        st[++top] = i;
    }
    free(st);
}

// The pattern behind next-greater, largest-rectangle and daily-temperatures.
// Each index is pushed and popped at most once, so O(n) overall.
func nextGreater(a []int) []int {
	res := make([]int, len(a))
	for i := range res {
		res[i] = -1
	}
	var stack []int // indices, values decreasing
	for i, x := range a {
		for len(stack) > 0 && a[stack[len(stack)-1]] < x {
			res[stack[len(stack)-1]] = x
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, i)
	}
	return res
}

// Sliding window maximum with a deque of indices.
func windowMax(a []int, k int) []int {
	var dq []int // indices; a[dq] decreasing
	var out []int
	for i, x := range a {
		for len(dq) > 0 && dq[0] <= i-k {
			dq = dq[1:] // left the window
		}
		for len(dq) > 0 && a[dq[len(dq)-1]] <= x {
			dq = dq[:len(dq)-1] // dominated, can never be the max
		}
		dq = append(dq, i)
		if i >= k-1 {
			out = append(out, a[dq[0]])
		}
	}
	return out
}
